FERN_DATA["software-engineering"] = {"units": [{"id": "requirements", "title": "Requirements in agile", "blurb": "How teams capture what the software should do: user stories versus use cases.", "topics": [{"id": "user-stories", "title": "User stories", "src": "CS 307 L1", "idea": "A user story is a short, high-level requirement that says who wants something, what they want and why. Details get added later, together with the team, as acceptance criteria.", "deep": "<p><strong>The template</strong></p>\n<div class=\"hl\"><pre><span></span><code>As a &lt;who&gt;, I want &lt;what&gt; so that &lt;why&gt;.\n</code></pre></div>\n\n<p>Example from your notes: <em>As a donor, I want to create an online account so my information is stored securely.</em></p>\n<p>Example for your AAC app: <em>As a nonverbal user, I want to tap a picture symbol so the app speaks the word out loud.</em> <span class=\"by\">Added by Fern</span></p>\n<ul>\n<li><strong>Written by:</strong> the product owner, with input from stakeholders.</li>\n<li><strong>Completed:</strong> progressively. The team refines stories together in Sprint Planning.</li>\n<li><strong>Scope:</strong> can grow and change. Bugs and missed needs simply become new stories.</li>\n<li><strong>Goal:</strong> a working product over exhaustive documentation.</li>\n</ul>\n<p><strong>Two purposes of user stories</strong></p>\n<ol>\n<li><strong>Collaboration:</strong> the team and product owner discuss each story and add acceptance criteria. This also builds shared understanding and team ownership.</li>\n<li><strong>Defining an MVP:</strong> stories make it easy to pick the smallest set of features that delivers real value.</li>\n</ol>\n<details><summary>Check yourself: name the three parts of a user story</summary><p>Who (the role), what (the action or feature) and why (the benefit).</p></details>", "text": "the template as a <who>, i want <what> so that <why>. example from your notes: as a donor, i want to create an online account so my information is stored securely. example for your aac app: as a nonverbal user, i want to tap a picture symbol so the app speaks the word out loud. added by fern written by: the product owner, with input from stakeholders. completed: progressively. the team refines stories together in sprint planning. scope: can grow and change. bugs and missed needs simply become new stories. goal: a working product over exhaustive documentation. two purposes of user stories collaboration: the team and product owner discuss each story and add acceptance criteria. this also builds shared understanding and team ownership. defining an mvp: stories make it easy to pick the smallest set of features that delivers real value. check yourself: name the three parts of a user story who (the role), what (the action or feature) and why (the benefit)."}, {"id": "acceptance-criteria", "title": "Acceptance criteria and the MVP", "src": "CS 307 L1", "idea": "Acceptance criteria are the specific actions and results that prove a story is done. The MVP (minimum viable product) is the smallest version of the product that gives the most benefit for the least time and effort.", "deep": "<p><strong>Acceptance criteria</strong></p>\n<ul>\n<li>Lower-level details: specific actions and the results they should produce.</li>\n<li><strong>Not</strong> part of the basic story. They're added later, when the team discusses the story.</li>\n<li>They line up closely with what a use case would describe.</li>\n</ul>\n<p>Example for the donor story:</p>\n<div class=\"hl\"><pre><span></span><code>Given I'm on the sign-up page\nWhen I enter a valid email and a password of 12+ characters\nThen my account is created and I'm signed in\nAnd my password is stored encrypted\n</code></pre></div>\n\n<p><em>(The Given/When/Then format is a common way to write criteria. Added by Fern)</em></p>\n<p><strong>MVP: minimum viable product</strong></p>\n<ul>\n<li>Maximum benefit for minimum time and effort.</li>\n<li>User stories support it; use cases have no MVP concept.</li>\n<li>In agile, short delivery cycles rest on agreeing what the MVP is.</li>\n</ul>\n<details><summary>Check yourself: when are acceptance criteria added?</summary><p>Later, during team discussion of the story (for example in Sprint Planning), not when the story is first written.</p></details>", "text": "acceptance criteria lower-level details: specific actions and the results they should produce. not part of the basic story. they're added later, when the team discusses the story. they line up closely with what a use case would describe. example for the donor story: given i'm on the sign-up page when i enter a valid email and a password of 12+ characters then my account is created and i'm signed in and my password is stored encrypted (the given/when/then format is a common way to write criteria. added by fern) mvp: minimum viable product maximum benefit for minimum time and effort. user stories support it; use cases have no mvp concept. in agile, short delivery cycles rest on agreeing what the mvp is. check yourself: when are acceptance criteria added? later, during team discussion of the story (for example in sprint planning), not when the story is first written."}, {"id": "use-cases", "title": "Use cases", "src": "CS 307 L1", "idea": "A use case is a very detailed description of how an actor interacts with a system, step by step, from the triggering event to the result. It includes the main flow and every alternate flow.", "deep": "<ul>\n<li><strong>Actor:</strong> a person or another system interacting with the system.</li>\n<li><strong>Basic course:</strong> the main, expected flow of steps.</li>\n<li><strong>Alternate courses:</strong> the other possible flows (errors, different choices).</li>\n<li>Aims at an <strong>end-to-end sequence</strong>: trigger → steps → result.</li>\n<li>Use cases line up more with <strong>acceptance criteria</strong> than with the user story itself.</li>\n</ul>\n<p><strong>How use cases are produced</strong></p>\n<ul>\n<li>Written by one person or a small group, usually <strong>without developers</strong>.</li>\n<li>Fully finished and signed off <strong>before</strong> the team sees them.</li>\n<li>Cover everything: intended functions, bugs, even misuse.</li>\n<li>Goal: remove all ambiguity so the team has everything it needs to develop and test.</li>\n</ul>\n<details><summary>Check yourself: define basic course and alternate course</summary><p>The basic course is the main, expected sequence of steps. Alternate courses are the other possible paths through the interaction, such as errors or different user choices.</p></details>", "text": "actor: a person or another system interacting with the system. basic course: the main, expected flow of steps. alternate courses: the other possible flows (errors, different choices). aims at an end-to-end sequence : trigger → steps → result. use cases line up more with acceptance criteria than with the user story itself. how use cases are produced written by one person or a small group, usually without developers . fully finished and signed off before the team sees them. cover everything: intended functions, bugs, even misuse. goal: remove all ambiguity so the team has everything it needs to develop and test. check yourself: define basic course and alternate course the basic course is the main, expected sequence of steps. alternate courses are the other possible paths through the interaction, such as errors or different user choices."}, {"id": "stories-vs-cases", "title": "User stories vs use cases", "src": "CS 307 L1", "idea": "Both capture requirements, but they differ in detail, author and timing. Only user stories fit agile, because they stay high level and grow through collaboration; use cases are finished up front with no team input.", "deep": "<div class=\"tw\"><table>\n<thead>\n<tr>\n<th></th>\n<th>User story</th>\n<th>Use case</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Detail</td>\n<td>high level; details added later</td>\n<td>extremely detailed</td>\n</tr>\n<tr>\n<td>Written by</td>\n<td>product owner + stakeholders</td>\n<td>one person or small group, usually no developers</td>\n</tr>\n<tr>\n<td>When finished</td>\n<td>progressively, in Sprint Planning</td>\n<td>fully signed off before the team sees it</td>\n</tr>\n<tr>\n<td>Collaboration</td>\n<td>the core purpose</td>\n<td>none; delivered final</td>\n</tr>\n<tr>\n<td>Scope</td>\n<td>grows and evolves</td>\n<td>covers everything up front</td>\n</tr>\n<tr>\n<td>MVP</td>\n<td>yes, defines it</td>\n<td>no MVP concept</td>\n</tr>\n<tr>\n<td>Goal</td>\n<td>working product</td>\n<td>remove all ambiguity</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Three angles to compare them:</strong> definition, purpose and timing.</p>\n<p><strong>Why use cases clash with agile:</strong> agile values working software, collaboration and responding to change. Use cases are written without the team, finalized before work starts, and try to settle everything in advance.</p>\n<details><summary>Check yourself: why does the use case approach conflict with agile values?</summary><p>Use cases are finished and signed off before the team is involved, so there's no collaboration, no room for requirements to evolve, and no MVP. Agile depends on all three.</p></details>", "text": "user story use case detail high level; details added later extremely detailed written by product owner + stakeholders one person or small group, usually no developers when finished progressively, in sprint planning fully signed off before the team sees it collaboration the core purpose none; delivered final scope grows and evolves covers everything up front mvp yes, defines it no mvp concept goal working product remove all ambiguity three angles to compare them: definition, purpose and timing. why use cases clash with agile: agile values working software, collaboration and responding to change. use cases are written without the team, finalized before work starts, and try to settle everything in advance. check yourself: why does the use case approach conflict with agile values? use cases are finished and signed off before the team is involved, so there's no collaboration, no room for requirements to evolve, and no mvp. agile depends on all three."}]}, {"id": "dev-methods", "title": "Development methods", "blurb": "Two ways to speed up delivery: rapid application development (RAD) and joint application development (JAD).", "topics": [{"id": "rad-basics", "title": "Rapid application development (RAD)", "src": "CS 307 L2", "idea": "RAD shortens the path from analysis to the end user by running coding, prototyping and testing at the same time instead of one after another. It works best when the product splits into modules and the designers are strong.", "deep": "<p><strong>Two prerequisites</strong></p>\n<ol>\n<li>The product can be <strong>modularized</strong> (broken into smaller segments).</li>\n<li>You have <strong>strong software designers</strong>.</li>\n</ol>\n<p><strong>Practices that speed RAD up</strong></p>\n<ul>\n<li><strong>Focus groups:</strong> learn what customers need and find useful right now.</li>\n<li><strong>Prototypes:</strong> build a working model for potential users to try (sometimes called beta testing) and give feedback on.</li>\n<li><strong>Interchangeable modules:</strong> reuse modules built for other applications.</li>\n<li><strong>Plan, schedule and communicate:</strong> a team that communicates well, accepts less formal reviews, and pushes improvements to the next version.</li>\n</ul>\n<p><strong>Trade-off:</strong> speed and flexibility, in exchange for less formal review and deferred improvements.</p>\n<details><summary>Check yourself: name four practices that speed up RAD</summary><p>Focus groups, prototypes, interchangeable (reusable) modules, and good planning, scheduling and communication.</p></details>", "text": "two prerequisites the product can be modularized (broken into smaller segments). you have strong software designers . practices that speed rad up focus groups: learn what customers need and find useful right now. prototypes: build a working model for potential users to try (sometimes called beta testing) and give feedback on. interchangeable modules: reuse modules built for other applications. plan, schedule and communicate: a team that communicates well, accepts less formal reviews, and pushes improvements to the next version. trade-off: speed and flexibility, in exchange for less formal review and deferred improvements. check yourself: name four practices that speed up rad focus groups, prototypes, interchangeable (reusable) modules, and good planning, scheduling and communication."}, {"id": "rad-model", "title": "The RAD model and tools", "src": "CS 307 L2", "idea": "RAD is an incremental model. After needs analysis and requirements are set, several teams build different modules in parallel, then combine them into the finished product.", "deep": "<div class=\"hl\"><pre><span></span><code>Needs analysis + requirements\n        │\n        ├── Team A: code ▸ prototype ▸ test  (module 1)\n        ├── Team B: code ▸ prototype ▸ test  (module 2)\n        └── Team C: code ▸ prototype ▸ test  (module 3)\n        │\n   Combine modules ▸ finished product\n</code></pre></div>\n\n<ul>\n<li>RAD <strong>combines the development and testing phases</strong> of the SDLC.</li>\n</ul>\n<p><strong>Advantages</strong></p>\n<ul>\n<li>Less development time.</li>\n<li>Reusable modules.</li>\n<li>Faster customer feedback.</li>\n<li>Changes are integrated throughout, because all parts of the design move forward together.</li>\n</ul>\n<p><strong>Tools:</strong> ones that are strong at <strong>automatic code generation</strong> cut development time. The lesson names Visual Studio, WaveMaker, Delphi RAD Studio, Lazarus IDE and Microsoft LightSwitch.</p>\n<details><summary>Check yourself: why do code-generating tools matter in RAD?</summary><p>RAD is all about speed. Tools that generate code automatically cut the time it takes to build each module.</p></details>", "text": "needs analysis + requirements │ ├── team a: code ▸ prototype ▸ test (module 1) ├── team b: code ▸ prototype ▸ test (module 2) └── team c: code ▸ prototype ▸ test (module 3) │ combine modules ▸ finished product rad combines the development and testing phases of the sdlc. advantages less development time. reusable modules. faster customer feedback. changes are integrated throughout, because all parts of the design move forward together. tools: ones that are strong at automatic code generation cut development time. the lesson names visual studio, wavemaker, delphi rad studio, lazarus ide and microsoft lightswitch. check yourself: why do code-generating tools matter in rad? rad is all about speed. tools that generate code automatically cut the time it takes to build each module."}, {"id": "jad-basics", "title": "Joint application development (JAD)", "src": "CS 307 L3", "idea": "JAD gathers and analyzes requirements through workshops that bring business and technical stakeholders into one room. Constant collaboration keeps the product matched to its agreed scope.", "deep": "<ul>\n<li>Common in <strong>agile</strong> environments, where short delivery cycles rest on agreeing the MVP.</li>\n<li>Needed whenever business and technology people must agree on development or testing requirements.</li>\n<li>Sessions last from a few hours to a day, or weeks on large projects.</li>\n<li>Started with computer systems but works more widely.</li>\n</ul>\n<p><strong>Key roles</strong></p>\n<div class=\"tw\"><table>\n<thead>\n<tr>\n<th>Role</th>\n<th>Responsibility</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Executive sponsor</td>\n<td>the ultimate decision maker</td>\n</tr>\n<tr>\n<td>Facilitator</td>\n<td>trained, appointed by executives and the customer; plans and runs sessions, links stakeholders</td>\n</tr>\n<tr>\n<td>Subject-matter expert</td>\n<td>turns the customer's requirements into a technical solution</td>\n</tr>\n<tr>\n<td>Documentation expert (scribe)</td>\n<td>clarifies discussion points and records them accurately</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Remember:</strong> the facilitator coordinates, but the <strong>executive sponsor decides</strong>.</p>\n<p><strong>Why it works:</strong> customer involvement plus group dynamics capture the user's view of the business need, which speeds up development.</p>\n<details><summary>Check yourself: who makes the key decisions in JAD, and what does the facilitator do instead?</summary><p>The executive sponsor decides. The facilitator plans and runs the sessions, keeps time, and connects the stakeholders.</p></details>", "text": "common in agile environments, where short delivery cycles rest on agreeing the mvp. needed whenever business and technology people must agree on development or testing requirements. sessions last from a few hours to a day, or weeks on large projects. started with computer systems but works more widely. key roles role responsibility executive sponsor the ultimate decision maker facilitator trained, appointed by executives and the customer; plans and runs sessions, links stakeholders subject-matter expert turns the customer's requirements into a technical solution documentation expert (scribe) clarifies discussion points and records them accurately remember: the facilitator coordinates, but the executive sponsor decides . why it works: customer involvement plus group dynamics capture the user's view of the business need, which speeds up development. check yourself: who makes the key decisions in jad, and what does the facilitator do instead? the executive sponsor decides. the facilitator plans and runs the sessions, keeps time, and connects the stakeholders."}, {"id": "jad-phases", "title": "The four JAD phases", "src": "CS 307 L3", "idea": "A JAD project runs in four phases: define the objectives, prepare the session, conduct the session, then document what was agreed.", "deep": "<ol>\n<li><strong>Define objectives:</strong> the facilitator and key stakeholders set the objectives and agenda (purpose, scope, expected outcome, participants) and send them out for review.</li>\n<li><strong>Session preparation:</strong> mostly the facilitator's job. Gather and send out information in advance, research the project and organization, and arrange the venue and time.</li>\n<li><strong>Session conduct:</strong> the facilitator leads everyone through the agenda and watches the time. Ground rules and the agenda are set early and agreed by participants.</li>\n<li><strong>Documentation:</strong> agreed deliverables become project documentation. The facilitator and scribe record everything; in multi-day sessions the scribe drafts each day's discussion. The final document goes to participants for <strong>sign-off</strong>.</li>\n</ol>\n<p><strong>Memory hook:</strong> Define → Prepare → Conduct → Document.</p>\n<details><summary>Check yourself: why does the scribe draft each day's notes in a multi-day session?</summary><p>So decisions are captured while they're fresh, participants can confirm them before the next day, and nothing is lost by the final sign-off.</p></details>", "text": "define objectives: the facilitator and key stakeholders set the objectives and agenda (purpose, scope, expected outcome, participants) and send them out for review. session preparation: mostly the facilitator's job. gather and send out information in advance, research the project and organization, and arrange the venue and time. session conduct: the facilitator leads everyone through the agenda and watches the time. ground rules and the agenda are set early and agreed by participants. documentation: agreed deliverables become project documentation. the facilitator and scribe record everything; in multi-day sessions the scribe drafts each day's discussion. the final document goes to participants for sign-off . memory hook: define → prepare → conduct → document. check yourself: why does the scribe draft each day's notes in a multi-day session? so decisions are captured while they're fresh, participants can confirm them before the next day, and nothing is lost by the final sign-off."}]}, {"id": "testing", "title": "Software testing", "blurb": "Why we test, the three testing methods, and the levels of testing from one module up to customer sign-off.", "topics": [{"id": "testing-purpose", "title": "What testing is for", "src": "CS 307 L4", "idea": "Testing examines a program's design and functionality to find errors and confirm it works as intended, like taste-testing a trial batch of soup before the competition.", "deep": "<p><strong>Two purposes</strong></p>\n<div class=\"tw\"><table>\n<thead>\n<tr>\n<th>Purpose</th>\n<th>Checks</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Quality assurance</td>\n<td>the program runs without errors</td>\n<td>a game quits unexpectedly: find the cause in the code and fix it before it passes</td>\n</tr>\n<tr>\n<td>Functional testing</td>\n<td>it does what it's supposed to do</td>\n<td>a player finishes Level 1 but gets no way to reach Level 2: a functional error</td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li>QA asks <strong>\"does it break?\"</strong> Functional testing asks <strong>\"does it do the job?\"</strong></li>\n</ul>\n<details><summary>Check yourself: give one example each of a QA problem and a functional problem</summary><p>QA: the app crashes when you press Save. Functional: Save works without crashing, but the file it writes is missing data the requirements say it must include.</p></details>", "text": "two purposes purpose checks example quality assurance the program runs without errors a game quits unexpectedly: find the cause in the code and fix it before it passes functional testing it does what it's supposed to do a player finishes level 1 but gets no way to reach level 2: a functional error qa asks \"does it break?\" functional testing asks \"does it do the job?\" check yourself: give one example each of a qa problem and a functional problem qa: the app crashes when you press save. functional: save works without crashing, but the file it writes is missing data the requirements say it must include."}, {"id": "testing-methods", "title": "Black-box, white-box and gray-box testing", "src": "CS 307 L4", "idea": "The three testing methods differ in how much the tester knows about the code: nothing (black-box), everything (white-box) or some (gray-box).", "deep": "<div class=\"tw\"><table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Tester knows the code?</th>\n<th>Viewpoint</th>\n<th>What they do</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Black-box</td>\n<td>No</td>\n<td>novice user</td>\n<td>uses the program and reports inconsistencies and errors</td>\n</tr>\n<tr>\n<td>White-box</td>\n<td>Yes, fully</td>\n<td>technical expert</td>\n<td>examines the code in detail with testing tools; finds code to fix or improve</td>\n</tr>\n<tr>\n<td>Gray-box</td>\n<td>Partly</td>\n<td>expert user</td>\n<td>knows the technical expectations and the code; reports problem areas</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Memory hook:</strong> black = can't see inside, white = can see everything, gray = in between.</p>\n<p><strong>In Java terms</strong> <span class=\"by\">Added by Fern</span></p>\n<ul>\n<li>A JUnit test you write for your own method, knowing its branches, is <strong>white-box</strong>.</li>\n<li>A classmate clicking through your JavaFX app without seeing the code is <strong>black-box</strong>.</li>\n</ul>\n<details><summary>Check yourself: which method would test every branch of an if/else in a method?</summary><p>White-box, because you need to see the code to know which branches exist.</p></details>", "text": "method tester knows the code? viewpoint what they do black-box no novice user uses the program and reports inconsistencies and errors white-box yes, fully technical expert examines the code in detail with testing tools; finds code to fix or improve gray-box partly expert user knows the technical expectations and the code; reports problem areas memory hook: black = can't see inside, white = can see everything, gray = in between. in java terms added by fern a junit test you write for your own method, knowing its branches, is white-box . a classmate clicking through your javafx app without seeing the code is black-box . check yourself: which method would test every branch of an if/else in a method? white-box, because you need to see the code to know which branches exist."}, {"id": "testing-best-practices", "title": "Testing best practices", "src": "CS 307 L4", "idea": "Plan the strategy before testing, test in small units, get feedback from real users, and fix errors before adding enhancements.", "deep": "<ol>\n<li><strong>Define the testing strategy</strong> before testing starts.</li>\n<li><strong>Test in small units:</strong> split the software into components and test each one separately (Level 1, then Level 2, and so on).</li>\n<li><strong>Get feedback from consumers:</strong> real users find errors and suggest improvements.</li>\n<li><strong>Consider all feedback, then prioritize:</strong></li>\n<li><strong>Errors first:</strong> crashes, hangs, login failures.</li>\n<li>\n<p><strong>Enhancements second:</strong> a harder level, an alternate path.</p>\n</li>\n<li>\n<p>Not all feedback has to be adopted. Decide what to keep.</p>\n</li>\n</ol>\n<details><summary>Check yourself: why fix errors before enhancements?</summary><p>Errors stop the software from working at all, while enhancements only improve something that already works. A new feature on top of a crash is still a crash.</p></details>", "text": "define the testing strategy before testing starts. test in small units: split the software into components and test each one separately (level 1, then level 2, and so on). get feedback from consumers: real users find errors and suggest improvements. consider all feedback, then prioritize: errors first: crashes, hangs, login failures. enhancements second: a harder level, an alternate path. not all feedback has to be adopted. decide what to keep. check yourself: why fix errors before enhancements? errors stop the software from working at all, while enhancements only improve something that already works. a new feature on top of a crash is still a crash."}, {"id": "testing-levels", "title": "The levels of testing", "src": "CS 307 L5", "idea": "Testing happens at several levels, each run by different people, moving from the smallest piece of code up to the customer's sign-off: unit, integration, smoke, system, business-level, user acceptance, formal acceptance.", "deep": "<div class=\"tw\"><table>\n<thead>\n<tr>\n<th>#</th>\n<th>Level</th>\n<th>Who</th>\n<th>Checks</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td>Unit</td>\n<td>the developer who wrote the module</td>\n<td>one module works to its requirements, on its own</td>\n</tr>\n<tr>\n<td>2</td>\n<td>Integration</td>\n<td>technical team</td>\n<td>modules that must talk (messages, transactions) can do so</td>\n</tr>\n<tr>\n<td>3</td>\n<td>Smoke</td>\n<td>part of the testing phase</td>\n<td>nothing major is broken; basic features work</td>\n</tr>\n<tr>\n<td>4</td>\n<td>System</td>\n<td>technical team</td>\n<td><strong>all</strong> components work together, not just pairs</td>\n</tr>\n<tr>\n<td>5</td>\n<td>Business-level</td>\n<td>business analysts or professional testers</td>\n<td>the software does what the requirements say, using test scripts</td>\n</tr>\n<tr>\n<td>6</td>\n<td>User acceptance (UAT)</td>\n<td>potential end users</td>\n<td>users get their say before deployment</td>\n</tr>\n<tr>\n<td>7</td>\n<td>Formal acceptance</td>\n<td>run in front of the sponsor or customer</td>\n<td>all tests pass and the customer signs off; then it deploys</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Why so many levels:</strong> software is too complex to get right the first time, so each level checks something different.</p>\n<p><strong>Integration vs system:</strong> integration tests modules that need to communicate, in pairs or small groups. System testing checks the <strong>whole</strong> thing together.</p>\n<p><strong>Unit test in Java</strong> <em>(Added by Fern; see Java → Unit testing with JUnit)</em></p>\n<div class=\"hl\"><pre><span></span><code><span class=\"nd\">@Test</span>\n<span class=\"kt\">void</span><span class=\"w\"> </span><span class=\"nf\">returnsLetterGradeA</span><span class=\"p\">()</span><span class=\"w\"> </span><span class=\"p\">{</span>\n<span class=\"w\">    </span><span class=\"n\">assertEquals</span><span class=\"p\">(</span><span class=\"sc\">'A'</span><span class=\"p\">,</span><span class=\"w\"> </span><span class=\"n\">Grades</span><span class=\"p\">.</span><span class=\"na\">letterFor</span><span class=\"p\">(</span><span class=\"mi\">93</span><span class=\"p\">));</span>\n<span class=\"p\">}</span>\n</code></pre></div>\n\n<details><summary>Check yourself: who performs unit testing, and what does it isolate?</summary><p>The developer who wrote the module. It isolates that one module and checks it against its requirements, independent of the others.</p></details>", "text": "# level who checks 1 unit the developer who wrote the module one module works to its requirements, on its own 2 integration technical team modules that must talk (messages, transactions) can do so 3 smoke part of the testing phase nothing major is broken; basic features work 4 system technical team all components work together, not just pairs 5 business-level business analysts or professional testers the software does what the requirements say, using test scripts 6 user acceptance (uat) potential end users users get their say before deployment 7 formal acceptance run in front of the sponsor or customer all tests pass and the customer signs off; then it deploys why so many levels: software is too complex to get right the first time, so each level checks something different. integration vs system: integration tests modules that need to communicate, in pairs or small groups. system testing checks the whole thing together. unit test in java (added by fern; see java → unit testing with junit) @test void returnslettergradea () { assertequals ( 'a' , grades . letterfor ( 93 )); } check yourself: who performs unit testing, and what does it isolate? the developer who wrote the module. it isolates that one module and checks it against its requirements, independent of the others."}, {"id": "smoke-testing", "title": "Smoke testing", "src": "CS 307 L5", "idea": "A smoke test is a quick health check that the build isn't badly broken and its main features basically work, like revving a repaired engine to see if it smokes.", "deep": "<ul>\n<li>Also called <strong>build verification</strong> or <strong>confidence testing</strong>.</li>\n<li>Covers only <strong>major features</strong>, not every component.</li>\n<li>Run before deeper testing, so time isn't wasted testing a broken build.</li>\n</ul>\n<details><summary>Check yourself: why is it called smoke testing?</summary><p>From hardware and engines: after a repair you power it on and see whether smoke comes out. If it does, there's no point testing further.</p></details>", "text": "also called build verification or confidence testing . covers only major features , not every component. run before deeper testing, so time isn't wasted testing a broken build. check yourself: why is it called smoke testing? from hardware and engines: after a repair you power it on and see whether smoke comes out. if it does, there's no point testing further."}, {"id": "test-scripts", "title": "Test scripts and business-level testing", "src": "CS 307 L5", "idea": "Script writers read the requirements and write steps of the form \"if you do A and B, you should get C\". Getting C is a pass; anything else is a fail.", "deep": "<div class=\"hl\"><pre><span></span><code>Test: Look up a customer's address\nSteps:  1. Search for \"Ms. Mary Jones\"\n        2. Open her record\nExpected: 42 Elm Street, Springfield\nResult:   PASS if that address appears, FAIL if any other address does\n</code></pre></div>\n\n<ul>\n<li><strong>\"As required\" is the standard.</strong> Business-level testing doesn't just ask whether it works; it asks whether it matches the requirements.</li>\n<li>Run by <strong>business analysts or professional testers</strong>.</li>\n</ul>\n<details><summary>Check yourself: what makes a test script result a pass or a fail?</summary><p>It passes only if the actual result matches the expected result written in the script. Any other result is a fail.</p></details>", "text": "test: look up a customer's address steps: 1. search for \"ms. mary jones\" 2. open her record expected: 42 elm street, springfield result: pass if that address appears, fail if any other address does \"as required\" is the standard. business-level testing doesn't just ask whether it works; it asks whether it matches the requirements. run by business analysts or professional testers . check yourself: what makes a test script result a pass or a fail? it passes only if the actual result matches the expected result written in the script. any other result is a fail."}, {"id": "uat-formal", "title": "UAT vs formal acceptance testing", "src": "CS 307 L5", "idea": "User acceptance testing lets potential end users try the software and give their opinion before launch. Formal acceptance testing is a set of tests run in front of the sponsor or customer, who must sign off before it deploys.", "deep": "<div class=\"tw\"><table>\n<thead>\n<tr>\n<th></th>\n<th>UAT</th>\n<th>Formal acceptance</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Who</td>\n<td>potential end users</td>\n<td>project sponsor or customer present</td>\n</tr>\n<tr>\n<td>Purpose</td>\n<td>users' opinion before deployment</td>\n<td>official sign-off</td>\n</tr>\n<tr>\n<td>Outcome</td>\n<td>feedback</td>\n<td>deploy only after all tests pass and the customer signs</td>\n</tr>\n</tbody>\n</table></div>\n<ul>\n<li>Companies are <strong>moving from UAT toward formal acceptance testing</strong>.</li>\n</ul>\n<details><summary>Check yourself: how does formal acceptance testing differ from UAT?</summary><p>UAT gathers end users' opinions. Formal acceptance is a structured series of tests run in front of the customer or sponsor, and the product can't deploy until every test passes and they sign off.</p></details>", "text": "uat formal acceptance who potential end users project sponsor or customer present purpose users' opinion before deployment official sign-off outcome feedback deploy only after all tests pass and the customer signs companies are moving from uat toward formal acceptance testing . check yourself: how does formal acceptance testing differ from uat? uat gathers end users' opinions. formal acceptance is a structured series of tests run in front of the customer or sponsor, and the product can't deploy until every test passes and they sign off."}]}, {"id": "evolution", "title": "Evolution and maintenance", "blurb": "Keeping software useful after release: maintenance types, the maintenance process, and refactoring.", "topics": [{"id": "software-evolution", "title": "Why software evolves", "src": "CS 307 L6", "idea": "Software evolution is the ongoing work of developing, maintaining and updating software. Change is inevitable, and since software is often a company's most critical asset, it has to be kept current.", "deep": "<p><strong>Why software changes</strong></p>\n<ul>\n<li>Requirements change.</li>\n<li>The environment changes (new OS, hardware, policies).</li>\n<li>Errors or security breaches are found.</li>\n<li>Equipment is added or removed.</li>\n<li>The system gets improvements.</li>\n</ul>\n<p><strong>Challenges of maintaining large systems</strong></p>\n<ul>\n<li>Finding the original documentation and records of changes since.</li>\n<li>Keeping changes in scale and within the current system's scope.</li>\n<li>Enough storage for the changes and the data.</li>\n<li>Finding and tracking changes in the source code (version control like Git helps).</li>\n<li>Managing growing complexity.</li>\n</ul>\n<p><strong>The goal:</strong> meet change requests with as little downtime and cost as possible.</p>\n<details><summary>Check yourself: name three challenges of maintaining a large system</summary><p>Any three of: missing documentation or change records, keeping changes in scope, storage, tracking changes in source code, growing complexity.</p></details>", "text": "why software changes requirements change. the environment changes (new os, hardware, policies). errors or security breaches are found. equipment is added or removed. the system gets improvements. challenges of maintaining large systems finding the original documentation and records of changes since. keeping changes in scale and within the current system's scope. enough storage for the changes and the data. finding and tracking changes in the source code (version control like git helps). managing growing complexity. the goal: meet change requests with as little downtime and cost as possible. check yourself: name three challenges of maintaining a large system any three of: missing documentation or change records, keeping changes in scope, storage, tracking changes in source code, growing complexity."}, {"id": "maintenance-types", "title": "The four types of maintenance", "src": "CS 307 L6", "idea": "Maintenance comes in four kinds: corrective (fix bugs), adaptive (keep up with a changed environment), perfective (add or improve features) and preventive (keep the code healthy for the long run).", "deep": "<div class=\"tw\"><table>\n<thead>\n<tr>\n<th>Type</th>\n<th>Purpose</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Corrective</strong></td>\n<td>fix bugs, errors and faults in released software. The <strong>most common</strong> type; users often report the defects</td>\n<td>a crash when saving an empty file</td>\n</tr>\n<tr>\n<td><strong>Adaptive</strong></td>\n<td>respond to environment changes (hardware, software, OS, policy) so it keeps working</td>\n<td>updating for a new macOS or Java version</td>\n</tr>\n<tr>\n<td><strong>Perfective</strong></td>\n<td>add features or enhancements users ask for; can improve performance</td>\n<td>adding dark mode</td>\n</tr>\n<tr>\n<td><strong>Preventive</strong></td>\n<td>protect longevity through optimization, restructuring and documentation</td>\n<td>refactoring a 300-line method, adding docs</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Memory hook:</strong> <strong>C</strong>orrect it, <strong>A</strong>dapt it, <strong>P</strong>erfect it, <strong>P</strong>rotect it.</p>\n<details><summary>Check yourself: which type is upgrading a JavaFX app to run on Java 21?</summary><p>Adaptive, because the environment changed and the app is being updated so it keeps working.</p></details>", "text": "type purpose example corrective fix bugs, errors and faults in released software. the most common type; users often report the defects a crash when saving an empty file adaptive respond to environment changes (hardware, software, os, policy) so it keeps working updating for a new macos or java version perfective add features or enhancements users ask for; can improve performance adding dark mode preventive protect longevity through optimization, restructuring and documentation refactoring a 300-line method, adding docs memory hook: c orrect it, a dapt it, p erfect it, p rotect it. check yourself: which type is upgrading a javafx app to run on java 21? adaptive, because the environment changed and the app is being updated so it keeps working."}, {"id": "maintenance-process", "title": "The seven-phase maintenance process", "src": "CS 307 L6", "idea": "A change moves through seven phases: change request, impact analysis, design, regression testing, acceptance testing, system implementation and system release.", "deep": "<ol>\n<li><strong>Change request (change management):</strong> receive the customer's request, check it can be done, plan it.</li>\n<li><strong>Impact analysis:</strong> document the change's effect on the current system, the resources needed and the constraints.</li>\n<li><strong>Design:</strong> start changing the software, based on the request and the impact analysis.</li>\n<li><strong>Regression testing:</strong> system testing to confirm the update works with the existing system, often in a virtual environment first.</li>\n<li><strong>Acceptance testing:</strong> a controlled release to a test group of end users and customers (regression, interoperability and functionality tests). Real testing happens at the user level.</li>\n<li><strong>System implementation:</strong> plan the launch with the least downtime.</li>\n<li><strong>System release:</strong> release it, tell users what changed, and offer any training.</li>\n</ol>\n<p><strong>Memory hook:</strong> Request → Impact → Design → Regress → Accept → Implement → Release.</p>\n<ul>\n<li><strong>Regression testing</strong> means re-testing existing features to make sure the change didn't break them. <span class=\"by\">Added by Fern</span></li>\n</ul>\n<details><summary>Check yourself: why is impact analysis done before design?</summary><p>You need to know how the change affects the existing system, what it will cost and what limits it has before deciding how to build it. Otherwise the design could break other parts or blow the budget.</p></details>", "text": "change request (change management): receive the customer's request, check it can be done, plan it. impact analysis: document the change's effect on the current system, the resources needed and the constraints. design: start changing the software, based on the request and the impact analysis. regression testing: system testing to confirm the update works with the existing system, often in a virtual environment first. acceptance testing: a controlled release to a test group of end users and customers (regression, interoperability and functionality tests). real testing happens at the user level. system implementation: plan the launch with the least downtime. system release: release it, tell users what changed, and offer any training. memory hook: request → impact → design → regress → accept → implement → release. regression testing means re-testing existing features to make sure the change didn't break them. added by fern check yourself: why is impact analysis done before design? you need to know how the change affects the existing system, what it will cost and what limits it has before deciding how to build it. otherwise the design could break other parts or blow the budget."}, {"id": "refactoring", "title": "What refactoring is", "src": "CS 307 L7", "idea": "Refactoring tidies the internal structure of code so it's easier to work with, without changing what the software does. Think of regularly reorganizing a closet.", "deep": "<p><strong>The test:</strong> same behavior, better structure.</p>\n<p><strong>Not refactoring</strong> (each one changes behavior):</p>\n<ul>\n<li>rewriting the code</li>\n<li>fixing bugs</li>\n<li>changing the interface</li>\n</ul>\n<p><strong>Why do it</strong></p>\n<ul>\n<li>Makes maintenance easier by simplifying structure.</li>\n<li>Helps people understand the code.</li>\n<li>Makes reusable pieces easier to create.</li>\n<li>Pulls developers into design decisions.</li>\n<li>Skipping it makes new features harder and more costly over time, especially in systems the business relies on and keeps changing.</li>\n</ul>\n<p><strong>History:</strong> first named \"factoring\" by Leo Brodie in 1984.</p>\n<p><strong>Small Java example: extract method</strong> <span class=\"by\">Added by Fern</span></p>\n<div class=\"hl\"><pre><span></span><code><span class=\"c1\">// Before: one method doing two jobs</span>\n<span class=\"kt\">void</span><span class=\"w\"> </span><span class=\"nf\">printReport</span><span class=\"p\">(</span><span class=\"n\">List</span><span class=\"o\">&lt;</span><span class=\"n\">Double</span><span class=\"o\">&gt;</span><span class=\"w\"> </span><span class=\"n\">grades</span><span class=\"p\">)</span><span class=\"w\"> </span><span class=\"p\">{</span>\n<span class=\"w\">    </span><span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"n\">sum</span><span class=\"w\"> </span><span class=\"o\">=</span><span class=\"w\"> </span><span class=\"mi\">0</span><span class=\"p\">;</span>\n<span class=\"w\">    </span><span class=\"k\">for</span><span class=\"w\"> </span><span class=\"p\">(</span><span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"n\">g</span><span class=\"w\"> </span><span class=\"p\">:</span><span class=\"w\"> </span><span class=\"n\">grades</span><span class=\"p\">)</span><span class=\"w\"> </span><span class=\"n\">sum</span><span class=\"w\"> </span><span class=\"o\">+=</span><span class=\"w\"> </span><span class=\"n\">g</span><span class=\"p\">;</span>\n<span class=\"w\">    </span><span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"n\">avg</span><span class=\"w\"> </span><span class=\"o\">=</span><span class=\"w\"> </span><span class=\"n\">sum</span><span class=\"w\"> </span><span class=\"o\">/</span><span class=\"w\"> </span><span class=\"n\">grades</span><span class=\"p\">.</span><span class=\"na\">size</span><span class=\"p\">();</span>\n<span class=\"w\">    </span><span class=\"n\">System</span><span class=\"p\">.</span><span class=\"na\">out</span><span class=\"p\">.</span><span class=\"na\">println</span><span class=\"p\">(</span><span class=\"s\">\"Average: \"</span><span class=\"w\"> </span><span class=\"o\">+</span><span class=\"w\"> </span><span class=\"n\">avg</span><span class=\"p\">);</span>\n<span class=\"p\">}</span>\n\n<span class=\"c1\">// After: same output, clearer structure</span>\n<span class=\"kt\">void</span><span class=\"w\"> </span><span class=\"nf\">printReport</span><span class=\"p\">(</span><span class=\"n\">List</span><span class=\"o\">&lt;</span><span class=\"n\">Double</span><span class=\"o\">&gt;</span><span class=\"w\"> </span><span class=\"n\">grades</span><span class=\"p\">)</span><span class=\"w\"> </span><span class=\"p\">{</span>\n<span class=\"w\">    </span><span class=\"n\">System</span><span class=\"p\">.</span><span class=\"na\">out</span><span class=\"p\">.</span><span class=\"na\">println</span><span class=\"p\">(</span><span class=\"s\">\"Average: \"</span><span class=\"w\"> </span><span class=\"o\">+</span><span class=\"w\"> </span><span class=\"n\">average</span><span class=\"p\">(</span><span class=\"n\">grades</span><span class=\"p\">));</span>\n<span class=\"p\">}</span>\n\n<span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"nf\">average</span><span class=\"p\">(</span><span class=\"n\">List</span><span class=\"o\">&lt;</span><span class=\"n\">Double</span><span class=\"o\">&gt;</span><span class=\"w\"> </span><span class=\"n\">grades</span><span class=\"p\">)</span><span class=\"w\"> </span><span class=\"p\">{</span>\n<span class=\"w\">    </span><span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"n\">sum</span><span class=\"w\"> </span><span class=\"o\">=</span><span class=\"w\"> </span><span class=\"mi\">0</span><span class=\"p\">;</span>\n<span class=\"w\">    </span><span class=\"k\">for</span><span class=\"w\"> </span><span class=\"p\">(</span><span class=\"kt\">double</span><span class=\"w\"> </span><span class=\"n\">g</span><span class=\"w\"> </span><span class=\"p\">:</span><span class=\"w\"> </span><span class=\"n\">grades</span><span class=\"p\">)</span><span class=\"w\"> </span><span class=\"n\">sum</span><span class=\"w\"> </span><span class=\"o\">+=</span><span class=\"w\"> </span><span class=\"n\">g</span><span class=\"p\">;</span>\n<span class=\"w\">    </span><span class=\"k\">return</span><span class=\"w\"> </span><span class=\"n\">sum</span><span class=\"w\"> </span><span class=\"o\">/</span><span class=\"w\"> </span><span class=\"n\">grades</span><span class=\"p\">.</span><span class=\"na\">size</span><span class=\"p\">();</span>\n<span class=\"p\">}</span>\n</code></pre></div>\n\n<details><summary>Check yourself: why is fixing a bug not refactoring?</summary><p>A bug fix changes what the software does. Refactoring must keep behavior exactly the same and only change structure.</p></details>", "text": "the test: same behavior, better structure. not refactoring (each one changes behavior): rewriting the code fixing bugs changing the interface why do it makes maintenance easier by simplifying structure. helps people understand the code. makes reusable pieces easier to create. pulls developers into design decisions. skipping it makes new features harder and more costly over time, especially in systems the business relies on and keeps changing. history: first named \"factoring\" by leo brodie in 1984. small java example: extract method added by fern // before: one method doing two jobs void printreport ( list < double > grades ) { double sum = 0 ; for ( double g : grades ) sum += g ; double avg = sum / grades . size (); system . out . println ( \"average: \" + avg ); } // after: same output, clearer structure void printreport ( list < double > grades ) { system . out . println ( \"average: \" + average ( grades )); } double average ( list < double > grades ) { double sum = 0 ; for ( double g : grades ) sum += g ; return sum / grades . size (); } check yourself: why is fixing a bug not refactoring? a bug fix changes what the software does. refactoring must keep behavior exactly the same and only change structure."}, {"id": "refactoring-principles", "title": "The four agile refactoring principles", "src": "CS 307 L7", "idea": "Refactor in small steps, let business needs drive it, make sure the whole team shares the approach, and be open with stakeholders about what it costs.", "deep": "<div class=\"tw\"><table>\n<thead>\n<tr>\n<th>Principle</th>\n<th>Meaning</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong>Keep it small</strong></td>\n<td>refactor in small, frequent steps; break big components into bite-size pieces to lower the risk of mistakes</td>\n</tr>\n<tr>\n<td><strong>Business catalysts</strong></td>\n<td>let business needs drive it, and limit it to the parts tied to the request. <strong>Exception:</strong> duplication the team spots should be cleaned up</td>\n</tr>\n<tr>\n<td><strong>Team cohesion</strong></td>\n<td>the team shares why and how to refactor, with common tools and techniques, so it can self-organize</td>\n</tr>\n<tr>\n<td><strong>Transparency</strong></td>\n<td>be open with stakeholders about costs; putting refactoring off raises future costs</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Summary:</strong> small, business-driven, team-shared, openly costed.</p>\n<details><summary>Check yourself: which principle allows an exception for duplicated code?</summary><p>Business catalysts. Refactoring is normally limited to the parts tied to a business request, but duplication the team notices should be cleaned up anyway.</p></details>", "text": "principle meaning keep it small refactor in small, frequent steps; break big components into bite-size pieces to lower the risk of mistakes business catalysts let business needs drive it, and limit it to the parts tied to the request. exception: duplication the team spots should be cleaned up team cohesion the team shares why and how to refactor, with common tools and techniques, so it can self-organize transparency be open with stakeholders about costs; putting refactoring off raises future costs summary: small, business-driven, team-shared, openly costed. check yourself: which principle allows an exception for duplicated code? business catalysts. refactoring is normally limited to the parts tied to a business request, but duplication the team notices should be cleaned up anyway."}, {"id": "se-practice", "title": "Practice with your own project", "src": "Fern", "idea": "The fastest way to make these ideas stick is to apply each one to a project you know, like your AAC app.", "deep": "<p><strong>10-minute warm-up:</strong> pick one card above, close it, and explain the main idea out loud in your own words. Then open it and check.</p>\n<p><strong>Apply it to your AAC app</strong> (about 10 to 15 minutes each)</p>\n<ol>\n<li>Write three user stories, then add two acceptance criteria to one of them.</li>\n<li>Pick your MVP: which stories are in the first version, and which wait?</li>\n<li>For one feature, list one test at each level: unit, integration, system, acceptance.</li>\n<li>Sort five imaginary bug reports and feature requests into the four maintenance types.</li>\n<li>Find one long method in any of your Java projects and refactor it without changing its output.</li>\n</ol>", "text": "10-minute warm-up: pick one card above, close it, and explain the main idea out loud in your own words. then open it and check. apply it to your aac app (about 10 to 15 minutes each) write three user stories, then add two acceptance criteria to one of them. pick your mvp: which stories are in the first version, and which wait? for one feature, list one test at each level: unit, integration, system, acceptance. sort five imaginary bug reports and feature requests into the four maintenance types. find one long method in any of your java projects and refactor it without changing its output."}]}], "ref": [{"id": "se-stories", "title": "User stories and use cases", "html": "<div class=\"hl\"><pre><span></span><code>As a &lt;who&gt;, I want &lt;what&gt; so that &lt;why&gt;.\n\nGiven &lt;starting situation&gt;\nWhen &lt;action&gt;\nThen &lt;expected result&gt;\n</code></pre></div>\n\n<div class=\"tw\"><table>\n<thead>\n<tr>\n<th></th>\n<th>User story</th>\n<th>Use case</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Detail</td>\n<td>high level</td>\n<td>very detailed</td>\n</tr>\n<tr>\n<td>Author</td>\n<td>product owner + stakeholders</td>\n<td>one person or small group</td>\n</tr>\n<tr>\n<td>Timing</td>\n<td>refined progressively</td>\n<td>finished before the team sees it</td>\n</tr>\n<tr>\n<td>Collaboration</td>\n<td>core purpose</td>\n<td>none</td>\n</tr>\n<tr>\n<td>MVP</td>\n<td>yes</td>\n<td>no</td>\n</tr>\n<tr>\n<td>Fits agile</td>\n<td>yes</td>\n<td>no</td>\n</tr>\n</tbody>\n</table></div>", "text": "as a <who>, i want <what> so that <why>. given <starting situation> when <action> then <expected result> user story use case detail high level very detailed author product owner + stakeholders one person or small group timing refined progressively finished before the team sees it collaboration core purpose none mvp yes no fits agile yes no"}, {"id": "se-rad", "title": "RAD at a glance", "html": "<div class=\"tw\"><table>\n<thead>\n<tr>\n<th>Aspect</th>\n<th>RAD</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Prerequisites</td>\n<td>modular product · strong designers</td>\n</tr>\n<tr>\n<td>Practices</td>\n<td>focus groups · prototypes · interchangeable modules · plan, schedule, communicate</td>\n</tr>\n<tr>\n<td>Model</td>\n<td>incremental; coding, prototyping and testing in parallel; modules combined at the end</td>\n</tr>\n<tr>\n<td>Advantages</td>\n<td>less time · reusable modules · fast feedback · changes integrated throughout</td>\n</tr>\n<tr>\n<td>Trade-off</td>\n<td>less formal review · improvements deferred</td>\n</tr>\n<tr>\n<td>Tools</td>\n<td>auto code generation: Visual Studio, WaveMaker, Delphi RAD Studio, Lazarus IDE, LightSwitch</td>\n</tr>\n</tbody>\n</table></div>", "text": "aspect rad prerequisites modular product · strong designers practices focus groups · prototypes · interchangeable modules · plan, schedule, communicate model incremental; coding, prototyping and testing in parallel; modules combined at the end advantages less time · reusable modules · fast feedback · changes integrated throughout trade-off less formal review · improvements deferred tools auto code generation: visual studio, wavemaker, delphi rad studio, lazarus ide, lightswitch"}, {"id": "se-jad", "title": "JAD roles and phases", "html": "<div class=\"tw\"><table>\n<thead>\n<tr>\n<th>Role</th>\n<th>Job</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Executive sponsor</td>\n<td>decides</td>\n</tr>\n<tr>\n<td>Facilitator</td>\n<td>plans and runs sessions</td>\n</tr>\n<tr>\n<td>Subject-matter expert</td>\n<td>turns needs into a technical solution</td>\n</tr>\n<tr>\n<td>Scribe</td>\n<td>records everything</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Phases:</strong> 1 Define objectives → 2 Session preparation → 3 Session conduct → 4 Documentation (sign-off)</p>", "text": "role job executive sponsor decides facilitator plans and runs sessions subject-matter expert turns needs into a technical solution scribe records everything phases: 1 define objectives → 2 session preparation → 3 session conduct → 4 documentation (sign-off)"}, {"id": "se-test-methods", "title": "Testing methods and priorities", "html": "<div class=\"tw\"><table>\n<thead>\n<tr>\n<th>Method</th>\n<th>Knows the code</th>\n<th>Viewpoint</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Black-box</td>\n<td>no</td>\n<td>novice user</td>\n</tr>\n<tr>\n<td>White-box</td>\n<td>fully</td>\n<td>technical expert</td>\n</tr>\n<tr>\n<td>Gray-box</td>\n<td>partly</td>\n<td>expert user</td>\n</tr>\n</tbody>\n</table></div>\n<div class=\"tw\"><table>\n<thead>\n<tr>\n<th>Purpose</th>\n<th>Question</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Quality assurance</td>\n<td>does it run without errors?</td>\n</tr>\n<tr>\n<td>Functional testing</td>\n<td>does it do its job?</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Best practices:</strong> strategy first · small units · user feedback · errors before enhancements</p>", "text": "method knows the code viewpoint black-box no novice user white-box fully technical expert gray-box partly expert user purpose question quality assurance does it run without errors? functional testing does it do its job? best practices: strategy first · small units · user feedback · errors before enhancements"}, {"id": "se-test-levels", "title": "Testing levels, in order", "html": "<div class=\"tw\"><table>\n<thead>\n<tr>\n<th>#</th>\n<th>Level</th>\n<th>Who</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td>Unit</td>\n<td>developer</td>\n</tr>\n<tr>\n<td>2</td>\n<td>Integration</td>\n<td>technical team</td>\n</tr>\n<tr>\n<td>3</td>\n<td>Smoke</td>\n<td>testing phase (quick health check)</td>\n</tr>\n<tr>\n<td>4</td>\n<td>System</td>\n<td>technical team</td>\n</tr>\n<tr>\n<td>5</td>\n<td>Business-level</td>\n<td>analysts / testers with scripts</td>\n</tr>\n<tr>\n<td>6</td>\n<td>User acceptance (UAT)</td>\n<td>end users</td>\n</tr>\n<tr>\n<td>7</td>\n<td>Formal acceptance</td>\n<td>in front of sponsor/customer; sign-off</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Test script:</strong> do A and B → expect C. C = pass, anything else = fail.</p>", "text": "# level who 1 unit developer 2 integration technical team 3 smoke testing phase (quick health check) 4 system technical team 5 business-level analysts / testers with scripts 6 user acceptance (uat) end users 7 formal acceptance in front of sponsor/customer; sign-off test script: do a and b → expect c. c = pass, anything else = fail."}, {"id": "se-maintenance", "title": "Maintenance", "html": "<div class=\"tw\"><table>\n<thead>\n<tr>\n<th>Type</th>\n<th>For</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Corrective</td>\n<td>fixing bugs (most common)</td>\n</tr>\n<tr>\n<td>Adaptive</td>\n<td>environment changes</td>\n</tr>\n<tr>\n<td>Perfective</td>\n<td>new features, enhancements</td>\n</tr>\n<tr>\n<td>Preventive</td>\n<td>optimization, restructuring, docs</td>\n</tr>\n</tbody>\n</table></div>\n<p><strong>Seven phases:</strong> 1 Change request → 2 Impact analysis → 3 Design → 4 Regression testing → 5 Acceptance testing → 6 System implementation → 7 System release</p>", "text": "type for corrective fixing bugs (most common) adaptive environment changes perfective new features, enhancements preventive optimization, restructuring, docs seven phases: 1 change request → 2 impact analysis → 3 design → 4 regression testing → 5 acceptance testing → 6 system implementation → 7 system release"}, {"id": "se-refactoring", "title": "Refactoring", "html": "<ul>\n<li><strong>Test:</strong> same behavior, better structure.</li>\n<li><strong>Not refactoring:</strong> rewriting, bug fixes, interface changes.</li>\n<li><strong>Principles:</strong> keep it small · business catalysts (except duplication) · team cohesion · transparency about cost.</li>\n<li><strong>Common moves:</strong> extract method · rename for clarity · remove duplication · split a large class · replace magic numbers with named constants. <span class=\"by\">Added by Fern</span></li>\n</ul>", "text": "test: same behavior, better structure. not refactoring: rewriting, bug fixes, interface changes. principles: keep it small · business catalysts (except duplication) · team cohesion · transparency about cost. common moves: extract method · rename for clarity · remove duplication · split a large class · replace magic numbers with named constants. added by fern"}], "vocab": [{"title": "Requirements", "terms": [["User story", "A high-level requirement describing who wants what and why."], ["Acceptance criteria", "Specific actions and results that prove a story is done. Added later, with the team."], ["Use case", "A very detailed description of an interaction between an actor and a system, from trigger to result."], ["Actor", "A person or system that interacts with the system in a use case."], ["Basic course", "The main, expected flow of a use case."], ["Alternate course", "Any other possible flow through a use case, such as an error path."], ["Product owner", "The person who writes and prioritizes user stories, with stakeholder input."], ["Stakeholder", "Anyone with an interest in the project: customers, users, sponsors, the team."], ["Sprint Planning", "The agile meeting where the team refines stories and plans the next sprint."], ["MVP", "Minimum viable product. The most benefit for the least time and effort."], ["Agile", "An approach that values working software, collaboration and responding to change."]]}, {"title": "Development methods", "terms": [["SDLC", "Software development life cycle: the phases from analysis to maintenance."], ["RAD", "Rapid application development. Runs coding, prototyping and testing in parallel to deliver faster."], ["Modularization", "Breaking a product into smaller, separate segments."], ["Prototype", "A working model users can try and give feedback on."], ["Focus group", "A group of customers asked what they need and find useful."], ["Interchangeable module", "A module built for one application and reused in another."], ["Incremental model", "Building software in pieces that are added together."], ["JAD", "Joint application development. Gathers requirements through workshops with business and technical stakeholders."], ["Executive sponsor", "The ultimate decision maker in JAD."], ["Facilitator", "The trained person who plans and runs JAD sessions."], ["Subject-matter expert", "Turns customer requirements into a technical solution."], ["Scribe", "The documentation expert who records JAD discussions."]]}, {"title": "Testing", "terms": [["Software testing", "Examining a program's design and function to find errors and confirm it works as intended."], ["Quality assurance", "Making sure the program runs without errors."], ["Functional testing", "Making sure the software performs its intended functions."], ["Black-box testing", "Testing without knowledge of the code, from a novice user's view."], ["White-box testing", "Testing with full knowledge of the code, from a technical expert's view."], ["Gray-box testing", "Testing with partial knowledge of the code, from an expert user's view."], ["Unit testing", "The developer testing one module on its own."], ["Integration testing", "Testing that modules which must communicate can do so."], ["Smoke testing", "A quick check that nothing major is broken. Also called build verification or confidence testing."], ["System testing", "Testing that all components work together."], ["Business-level testing", "Testers running scripts to confirm the software does what the requirements say."], ["Test script", "Steps with an expected result: do A and B, expect C."], ["User acceptance testing (UAT)", "Potential end users trying the software before deployment."], ["Formal acceptance testing", "Tests run in front of the sponsor or customer, who must sign off before deployment."]]}, {"title": "Evolution and maintenance", "terms": [["Software evolution", "The ongoing process of developing, maintaining and updating software."], ["Corrective maintenance", "Fixing bugs and faults in released software. The most common type."], ["Adaptive maintenance", "Updating software so it keeps working after its environment changes."], ["Perfective maintenance", "Adding features or enhancements based on user requirements."], ["Preventive maintenance", "Protecting longevity through optimization, restructuring and documentation."], ["Change request", "A customer's request for a modification. The first maintenance phase."], ["Impact analysis", "Documenting a change's effect on the system, the resources it needs and its constraints."], ["Regression testing", "Re-testing to make sure a change didn't break what already worked."], ["Interoperability testing", "Checking that the software works with other systems it connects to."], ["Refactoring", "Improving code structure without changing its behavior."], ["Technical debt", "The growing future cost of putting off cleanup and refactoring."]]}], "res": [{"title": "Agile and requirements", "items": [{"title": "Manifesto for Agile Software Development", "url": "https://agilemanifesto.org/", "note": "The four values and twelve principles behind agile. One page; worth reading once."}, {"title": "The Scrum Guide", "url": "https://scrumguides.org/", "note": "The official definition of Scrum roles and events, including Sprint Planning and the product owner."}, {"title": "User stories (Atlassian)", "url": "https://www.atlassian.com/agile/project-management/user-stories", "note": "Plain-language guide with examples and templates."}]}, {"title": "Testing", "items": [{"title": "ISTQB Glossary", "url": "https://glossary.istqb.org/", "note": "The standard definitions of testing terms used across the industry."}, {"title": "JUnit", "url": "https://junit.org/", "note": "Write your own unit tests in Java. See the Java page's unit testing card."}]}, {"title": "Refactoring", "items": [{"title": "Refactoring.Guru", "url": "https://refactoring.guru/refactoring", "note": "Visual catalog of code smells and refactoring moves, with Java examples."}, {"title": "Refactoring (Martin Fowler)", "url": "https://refactoring.com/", "note": "The classic reference on refactoring and its catalog of techniques."}]}], "files": [["CS 307 Study Guide, Chapter 4", "Development and testing methods: 7 lessons on user stories, RAD, JAD, testing methods and levels, software evolution and refactoring. Its Check yourself questions are inside each card, with answers hidden."]]};
